contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 artId1, uint256 artId2, uint256 fee1, uint256 fee2) public payable {
        require(address(this).balance >= 0, "balance");

        uint256 before = c.tokenIdCounter();
        require(before == 1, "counter initial");

        uint256 returned1 = c.createArtFromFactory{value: 0}(artId1);
        uint256 after1 = c.tokenIdCounter();
        require(after1 == before + 1, "increment 1");
        require(returned1 == before, "returned 1");
        require(c.getTokenIdFromFactoryArtId(artId1) == returned1, "mapping 1");

        uint256 returned2 = c.createArtFromFactory{value: 0}(artId2);
        uint256 after2 = c.tokenIdCounter();
        require(after2 == after1 + 1, "increment 2");
        require(returned2 == after1, "returned 2");
        require(c.getTokenIdFromFactoryArtId(artId2) == returned2, "mapping 2");

        assert(after1 == before + 1 && after2 == after1 + 1 && returned1 == before && returned2 == after1);
    }

    receive() external payable {}
}

